steps.checkScript:
# Tests backup from funcs.sh in a temp folder (the student's files stay untouched).
[ -f funcs.sh ] || { echo "Die Datei funcs.sh gibt es noch nicht."; exit 1; }
t=$(mktemp -d) || exit 1
trap 'rm -rf -- "$t"' EXIT
cp -- funcs.sh "$t/" && cd -- "$t" || exit 1
echo "Testinhalt" > probe.txt

run() { timeout 10 bash -c 'source ./funcs.sh >/dev/null 2>&1; declare -F backup >/dev/null || exit 42; backup "$@"' backup "$@" </dev/null; }

out=$(run 2>err.txt); rc=$?
[ "$rc" -eq 42 ] && { echo "In funcs.sh gibt es noch keine Funktion backup."; exit 1; }
[ "$rc" -ne 0 ] || { echo "backup ohne Argument soll mit return 1 enden (Exit-Code ungleich 0)."; exit 1; }
[ -s err.txt ] || { echo "backup ohne Argument soll eine Hilfe auf stderr ausgeben (echo … >&2)."; exit 1; }
[ -z "$out" ] || { echo "Die Hilfe gehört auf stderr, nicht auf stdout: echo \"…\" >&2"; exit 1; }

run probe.txt probe.txt >/dev/null 2>&1 && { echo "backup mit zwei Argumenten soll ebenfalls mit return 1 abbrechen."; exit 1; }

run probe.txt >/dev/null 2>&1 || { echo "backup probe.txt soll funktionieren (Exit-Code 0)."; exit 1; }
if [ ! -f probe.txt.bak ] || ! cmp -s probe.txt probe.txt.bak; then
  echo "backup probe.txt soll eine Kopie probe.txt.bak anlegen."
  exit 1
fi
echo "Super – backup prüft seine Argumente, meldet Fehler auf stderr und legt die Kopie an."
